package com.wizzadrds.theworldremembers.knowledge; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class KnowledgeManagerTest{@Test void rumorLosesConfidence(){var source=new KnowledgeFact("e","death",UUID.randomUUID(),null,1,1,1.0,KnowledgeOrigin.DIRECT);var reported=new KnowledgeFact("e","death",source.subject(),UUID.randomUUID(),1,2,.75,KnowledgeOrigin.REPORTED);assertTrue(reported.confidence()<source.confidence());assertNotEquals(KnowledgeOrigin.DIRECT,reported.origin());}}